import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"43、【夬】 乾下兑上","description":"横渠易说 - 43、【夬】 乾下兑上","frontmatter":{"title":"43、【夬】 乾下兑上","description":"横渠易说 - 43、【夬】 乾下兑上"},"headers":[],"relativePath":"zh/classics/hengqu/045.md","filePath":"zh/classics/hengqu/045.md"}'),l={name:"zh/classics/hengqu/045.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_43、【夬】-乾下兑上" tabindex="-1">43、【夬】 乾下兑上 <a class="header-anchor" href="#_43、【夬】-乾下兑上" aria-label="Permalink to “43、【夬】 乾下兑上”">​</a></h1><p>益而不已必决，故受之以夬。</p><h3 id="彖曰-夬-决也-刚决柔也-健而说-决而和。-扬于王庭-柔乘五刚也-孚号有厉-其危乃光也。-告自邑-不利即戎-所尚乃穷也-利有攸往-刚长乃终也。" tabindex="-1">彖曰：夬，决也，刚决柔也，健而说，决而和。“扬于王庭”，柔乘五刚也；“孚号有厉”，其危乃光也。“告自邑，不利即戎”所尚乃穷也；“利有攸往”，刚长乃终也。 <a class="header-anchor" href="#彖曰-夬-决也-刚决柔也-健而说-决而和。-扬于王庭-柔乘五刚也-孚号有厉-其危乃光也。-告自邑-不利即戎-所尚乃穷也-利有攸往-刚长乃终也。" aria-label="Permalink to “彖曰：夬，决也，刚决柔也，健而说，决而和。“扬于王庭”，柔乘五刚也；“孚号有厉”，其危乃光也。“告自邑，不利即戎”所尚乃穷也；“利有攸往”，刚长乃终也。”">​</a></h3><p>不可以必胜而忽慢，故能矜慎则愈光也。 除恶务本，故利有所进而后为德乃终。</p><h3 id="象曰-泽上于天-夬-君子以施禄及下-居德则忌。" tabindex="-1">象曰：泽上于天，夬，君子以施禄及下，居德则忌。 <a class="header-anchor" href="#象曰-泽上于天-夬-君子以施禄及下-居德则忌。" aria-label="Permalink to “象曰：泽上于天，夬，君子以施禄及下，居德则忌。”">​</a></h3><p>君子道长，故非德之禁可以必行，然不可恃令之行，无恩以及下也。</p><h3 id="初九-壮于前趾-往不胜为咎。-象曰-不胜而往-咎也。" tabindex="-1">初九，壮于前趾，往不胜为咎。 象曰：不胜而往，咎也。 <a class="header-anchor" href="#初九-壮于前趾-往不胜为咎。-象曰-不胜而往-咎也。" aria-label="Permalink to “初九，壮于前趾，往不胜为咎。 象曰：不胜而往，咎也。”">​</a></h3><p>言能虑胜而往则无咎。</p><h3 id="九二-惕号-莫夜有戎勿恤。-象曰-有戎勿恤-得中道也。" tabindex="-1">九二，惕号，莫夜有戎勿恤。 象曰：“有戎勿恤”，得中道也。 <a class="header-anchor" href="#九二-惕号-莫夜有戎勿恤。-象曰-有戎勿恤-得中道也。" aria-label="Permalink to “九二，惕号，莫夜有戎勿恤。 象曰：“有戎勿恤”，得中道也。”">​</a></h3><p>警惧申号，能孚号而有厉也。以必胜之刚，决至危之柔，能自危虑，虽有戎何恤!能得中道，故刚而不暴。</p><h3 id="九三-壮于頄-有凶。君子夬夬-独行遇雨若濡-有愠-无咎。-象曰-君子夬夬-终无咎也。" tabindex="-1">九三，壮于頄，有凶。君子夬夬，独行遇雨若濡，有愠，无咎。 象曰：“君子夬夬”，终无咎也。 <a class="header-anchor" href="#九三-壮于頄-有凶。君子夬夬-独行遇雨若濡-有愠-无咎。-象曰-君子夬夬-终无咎也。" aria-label="Permalink to “九三，壮于頄，有凶。君子夬夬，独行遇雨若濡，有愠，无咎。 象曰：“君子夬夬”，终无咎也。”">​</a></h3><p>九三以阳居阳，进决于上，是壮于頄也。不得中道，过壮或凶，故曰“有凶”。君子明于事几，能夬于用夬，进而缓之以善其终，不假用众，故曰“独行”；使之悦从，故曰“遇雨若濡”。君子之心终［无系累］，故必有愠。虽其有愠，于正无害，故［曰］“无咎”，［故］君子之道绰然余裕，终不为咎也。</p><h3 id="九四-臀无肤-其行次且-牵羊悔亡-闻言不信。-象曰-其行次且-位不当也。-闻言不信-聪不明也。" tabindex="-1">九四，臀无肤，其行次且，牵羊悔亡，闻言不信。 象曰：“其行次且”，位不当也。“闻言不信”，聪不明也。 <a class="header-anchor" href="#九四-臀无肤-其行次且-牵羊悔亡-闻言不信。-象曰-其行次且-位不当也。-闻言不信-聪不明也。" aria-label="Permalink to “九四，臀无肤，其行次且，牵羊悔亡，闻言不信。 象曰：“其行次且”，位不当也。“闻言不信”，聪不明也。”">​</a></h3><p>一阴在上，众阳争趋，三其正应，己独乘之，故行止皆凶。牵羊者必让而先之，则为力也易，溺于所趋，必不能用，故曰“闻言不信”，溺于心者，听必不聪。</p><h3 id="九五-苋陆夬夬-中行无咎。-象曰-中行无咎-中未光也。" tabindex="-1">九五，苋陆夬夬，中行无咎。 象曰：“中行无咎”，中未光也。 <a class="header-anchor" href="#九五-苋陆夬夬-中行无咎。-象曰-中行无咎-中未光也。" aria-label="Permalink to “九五，苋陆夬夬，中行无咎。 象曰：“中行无咎”，中未光也。”">​</a></h3><p>阳近于阴，不能无累，故必正其行然后免咎。</p><h3 id="上六-无号终有凶。-象曰-无号之凶-终不可长也。" tabindex="-1">上六，无号终有凶。 象曰：无号之凶，终不可长也。 <a class="header-anchor" href="#上六-无号终有凶。-象曰-无号之凶-终不可长也。" aria-label="Permalink to “上六，无号终有凶。 象曰：无号之凶，终不可长也。”">​</a></h3>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
